const clean=(value:string)=>value.replace(/ /g,' ');
const own=(id:string)=>{const index=definitions.findIndex(d=>d.id===id);return{definition:definitions[index],content:contents[index],localization:localizations[index]};};
const defaults=(d:CalculatorDefinitionV2)=>Object.fromEntries(d.presentation.fields.map(f=>[f.name,f.defaultValue!])) as Record<string,string|number|boolean>;
const runtime=(id:string)=>{const o=own(id);return{compute:o.definition.compute,validate:o.definition.validate,contextualField:o.definition.contextualField,localization:o.localization};};

describe('65 actual published identities and subject-owned candidate bodies (no MAIN registry import)',()=>{
 for(const d of definitions)for(const locale of locales){
  it(`${d.id}/${locale}: keep published identity, defaults, FAQ order and complete native body`,()=>{
   const index=definitions.indexOf(d);const copy=(locale==='ru'?d.presentation:d.copy![locale]!) as typeof d.presentation;
   const baseline=identity[`${d.id}:${locale}` as keyof typeof identity];
   expect(copy.name).toBe(baseline.name);expect(copy.h1).toBe(baseline.h1);expect(copy.slug).toBe(baseline.slug);
   expect(defaults(d)).toEqual(baseline.defaults);
   expect(copy.longDescription).toBe(contents[index][locale].longDescription);
   expect(copy.howItWorks).toBe(contents[index][locale].howItWorks);
   expect(copy.example).toBe(contents[index][locale].example);
   expect(copy.faq!.map(f=>f.q)).toEqual(baseline.questions);expect(copy.faq!.length).toBeGreaterThanOrEqual(4);
   expect(copy.longDescription!.length).toBeGreaterThan(150);expect(copy.howItWorks!.length).toBeGreaterThan(75);
   expect(copy.example!.length).toBeGreaterThan(75);expect(copy.howToUse!.length).toBeGreaterThanOrEqual(3);
   expect(copy.disclaimer!.length).toBeGreaterThan(80);expect(JSON.stringify(copy)).not.toMatch(/undefined|NaN|Infinity/);
   for(const field of d.presentation.fields){const helped=d.contextualField!(field,defaults(d),locale);if(helped.help)expect(helped.help).not.toMatch(/undefined|NaN|Infinity/);}
  });
 }
});

describe('all65 independently stated normal examples remain numerically true',()=>{
 for(const c of normal)it(`${c.id}/${c.locale}: literal published normal values`,()=>{
  const d=own(c.id).definition;const result=d.compute({...defaults(d),...c.inputs});
  expect(clean(result.primary.value)).toBe(c.primary);
  for(const[label,value]of c.rows)expect(clean(result.secondary.find(r=>r.label===label)!.value)).toBe(value);
 });
});

describe('native calculation values and financial field units',()=>{
 for(const d of definitions)for(const locale of locales)it(`${d.id}/${locale}: real result localization plus own field-help`,()=>{
  const index=definitions.indexOf(d);const raw=d.compute(defaults(d));const translated=localizeResult(raw,locale,d.id,runtime(d.id));
  expect(translated.primary.value).not.toBe('—');
  if(locale!=='ru'){
   expect(translated.primary.label).toBe(localizations[index][locale]!.results![raw.primary.label]);
   expect(JSON.stringify(translated)).not.toMatch(/[ыъёэ]/i);
   for(const field of d.presentation.fields){if(field.unit==='₽'){
    expect(localizations[index][locale]!.fields![field.name]).not.toMatch(/[₽$€₴]/);
    const moneyProbe=localizeResult({primary:{label:raw.primary.label,value:'1,00 ₽'},secondary:[]},locale,d.id,runtime(d.id));expect(moneyProbe.primary.value).toContain({en:'$',uk:'₴',de:'€',es:'€'}[locale]);expect(moneyProbe.primary.value).not.toContain('₽');
   }}
  }
 });
});

describe('whole counts inspect raw native form/query input before normalization',()=>{
 for(const[id,name]of [['installment','months'],['market-cap','shares'],['workday-cost','days']] as const)for(const locale of locales){
  const raw=locale==='en'?'1.00000000000000001':'1,00000000000000001';
  it(`${id}/${locale}: tiny nonzero fraction cannot round onto whole1`,()=>{
   const d=own(id).definition;const values={...defaults(d),[name]:raw};expect(normalizeValues(d.presentation.fields,values,locale)[name]).toBe(1);
   const errors=validateValues(id,d.presentation.fields,values,locale,runtime(id));
   const key='Количество должно быть целым в допустимом диапазоне';expect(errors[name]).toBe(locale==='ru'?key:own(id).localization[locale]!.values![key]);
   expect(d.compute(values).primary.value).toBe('—');
  });
  it(`${id}/${locale}: offending scientific query is preserved and rejected natively`,()=>{
   const d=own(id).definition;const literal='1.00000000000000001e0';
   const restored=readValuesFromSearch(d.presentation.fields,defaults(d),`?${name}=${literal}`,locale);expect(restored[name]).toBe(literal);
   const error=validateValues(id,d.presentation.fields,restored,locale,runtime(id))[name];expect(error).toBeTruthy();if(locale!=='ru')expect(error).not.toMatch(/[ыъёэ]/i);
   expect(new URLSearchParams(buildCalculatorQueryString(d.presentation.fields,restored,locale)).get(name)).toBe(literal);
  });
  it(`${id}/${locale}: whole number is accepted; boolean and unsafe counts remain errors`,()=>{
   const d=own(id).definition;expect(validateValues(id,d.presentation.fields,{...defaults(d),[name]:1},locale,runtime(id))[name]).toBeUndefined();
   expect(validateValues(id,d.presentation.fields,{...defaults(d),[name]:true},locale,runtime(id))[name]).toBeTruthy();
   expect(validateValues(id,d.presentation.fields,{...defaults(d),[name]:'9007199254740992'},locale,runtime(id))[name]).toBeTruthy();
  });
 }
});

describe('legitimate fractional and optional fields stay supported',()=>{
 for(const locale of locales){
  for(const[id,changes]of [['home-equity',{years:1/12}],['max-loan',{years:.1}],['overtime',{normalHours:.5,overtimeHours:.5}],['risk-reward',{qty:.5}],['vacation-accrual',{monthsWorked:.5,daysUsed:.5}],['workday-cost',{hours:.5}]] as const){
   it(`${id}/${locale}: meaningful fractional units pass the actual form validator`,()=>{
    const d=own(id).definition;const values={...defaults(d),...changes};expect(validateValues(id,d.presentation.fields,values,locale,runtime(id))).toEqual({});expect(d.compute(values).primary.value).not.toBe('—');
   });
  }
  for(const[id,name]of [['installment','down'],['rental-yield','annualCosts'],['risk-reward','qty']] as const)it(`${id}/${locale}: optional blank means0 without changing nonzero numerical default`,()=>{
   const d=own(id).definition;expect(d.presentation.fields.find(f=>f.name===name)!.optional).toBe(true);const values={...defaults(d),[name]:''};expect(validateValues(id,d.presentation.fields,values,locale,runtime(id))).toEqual({});
   expect(d.compute(normalizeValues(d.presentation.fields,values,locale))).toEqual(d.compute({...defaults(d),[name]:0}));
  });
 }
});

describe('errors and active-mode contracts use native owned bundles',()=>{
 for(const d of definitions)for(const locale of locales)it(`${d.id}/${locale}: malformed active numeric input produces explicit native error`,()=>{
  const field=d.presentation.fields.find(f=>f.type==='number')!;const r=d.compute({...defaults(d),[field.name]:true});expect(r.primary.value).toBe('—');
  const localized=localizeResult(r,locale,d.id,runtime(d.id));if(locale!=='ru'){
   expect(localized.secondary[0].value).toBe(own(d.id).localization[locale]!.values![r.secondary[0].value]);expect(localized.secondary[0].value).not.toMatch(/[ыъёэ]/i);
  }
 });
 for(const locale of locales)for(const[id,mode,active,inactive,value]of [
  ['market-cap','mode','price','cap','cap'],['market-cap','mode','cap','price','price'],
  ['rental-yield','rentMode','annualRent','monthlyRent','annual'],['rental-yield','rentMode','monthlyRent','annualRent','monthly'],
  ['salary-raise','mode','newSalary','raisePct','fromNew'],['salary-raise','mode','raisePct','newSalary','fromPct'],
 ] as const)it(`${id}/${locale}/${value}: inactive malformed input ignored and omitted from share`,()=>{
  const d=own(id).definition;const values={...defaults(d),[mode]:value,[inactive]:true};expect(validateValues(id,d.presentation.fields,values,locale,runtime(id))).toEqual({});expect(d.compute(values).primary.value).not.toBe('—');
  expect(new URLSearchParams(buildCalculatorQueryString(d.presentation.fields,values,locale)).has(inactive)).toBe(false);
  expect(validateValues(id,d.presentation.fields,{...values,[active]:true},locale,runtime(id))[active]).toBeTruthy();
 });
});

