describe('26 individually fixed published boundary claims',()=>{for(const[cIndex,c]of publishedBoundaries.entries())it(`${c.id}/${cIndex}: ${c.independentReason}`,()=>{const d=own(c.id).definition;const r=d.compute({...defaults(d),...c.inputs});expect(clean(r.primary.value)).toBe(c.primary);for(const[label,value]of c.rows)expect(clean(r.secondary.find(x=>x.label===label)!.value)).toBe(value);for(const label of c.absent)expect(r.secondary.some(x=>x.label===label)).toBe(false);if(c.id==='risk-reward'&&c.inputs.target===c.inputs.entry)expect(r.secondary.some(x=>x.label==='Внимание'&&x.accent==='red')).toBe(true);});});
